from bisect import bisect_left, insort

def maxRectSumAtMost(matrix, k):
    m, n = len(matrix), len(matrix[0])
    if m > n:
        matrix = [list(col) for col in zip(*matrix)]
        m, n = n, m
    best = None
    for top in range(m):
        col = [0] * n
        for bottom in range(top, m):
            row = matrix[bottom]
            for c in range(n):
                col[c] += row[c]
            seen = [0]
            pref = 0
            for c in range(n):
                pref += col[c]
                i = bisect_left(seen, pref - k)
                if i < len(seen):
                    cand = pref - seen[i]
                    if best is None or cand > best:
                        best = cand
                        if best == k:
                            return k
                insort(seen, pref)
    return best
